# frozen_string_literal: true

module Rouge
  module Lexers
    class Expressif < RegexLexer
      title "Expressif"
      desc "The Expressif transformation expression language"
      tag "expressif"
      filenames "*.expr", "*.expressif"

      state :root do
        rule %r/(→)([^\r\n]*)/, groups(Operator, Generic::Output)
        rule %r/\s+/, Text::Whitespace
        rule %r/#"(?:\\.|[^"\\])*"/, Literal::Date
        rule %r/"(?:\\.|[^"\\])*"/, Str
        rule %r/`(?:\\.|[^`\\])*`/, Str
        rule %r/(?:#blank|#empty|#false|#null|#true)\b/i, Keyword::Constant
        rule %r/(?::array|:boolean|:date|:datetime|:decimal|:duration|:integer|:null|:numeric|:record|:scalar|:structured|:temporal|:text|:time|:tuple|:weekday|:year-month)\b/i, Keyword::Type
        rule %r/@(?:_|[A-Za-z_][\w-]*)/, Name::Variable
        rule %r/\^?\.(?:[A-Za-z_][\w-]*|\d+)/, Name::Property
        rule %r/\[(?:[A-Za-z_][\w-]*|\d+)\]/, Name::Property
        rule %r/\b(?:numeric-to-human-readable-format-decimal-bytes|numeric-to-human-readable-format-binary-bytes|numeric-to-human-readable-format-decimal|text-is-sorted-before-or-equivalent-to|text-is-sorted-after-or-equivalent-to|dateTime-to-previous-weekday-or-same|human-readable-format-decimal-bytes|dateTime-is-before-or-same-instant|dateTime-is-in-the-future-or-today|human-readable-format-binary-bytes|numeric-to-greatest-common-divisor|path-to-filename-without-extension|temporal-to-previous-business-days|dateTime-is-after-or-same-instant|dateTime-is-within-upcoming-month|is-sorted-before-or-equivalent-to|numeric-to-lowest-common-multiple|dateTime-is-in-the-future-or-now|dateTime-is-in-the-past-or-today|dateTime-is-within-current-month|dateTime-is-within-previous-days|dateTime-is-within-upcoming-week|dateTime-is-within-upcoming-year|dateTime-to-next-weekday-or-same|is-sorted-after-or-equivalent-to|numeric-is-greater-than-or-equal|dateTime-is-within-current-week|dateTime-is-within-current-year|dateTime-is-in-the-past-or-now|dateTime-to-hour-minute-second|sorted-before-or-equivalent-to|temporal-to-next-business-days|dateTime-is-within-last-month|dateTime-to-iso-year-week-day|file-to-creation-datetime-utc|human-readable-format-decimal|numeric-is-less-than-or-equal|sorted-after-or-equivalent-to|text-to-retain-numeric-symbol|dateTime-is-within-last-week|dateTime-is-within-last-year|dateTime-is-within-next-days|dateTime-to-change-of-minute|dateTime-to-change-of-second|dateTime-to-iso-week-of-year|dateTime-to-previous-weekday|dateTime-to-second-of-minute|text-to-count-distinct-chars|text-to-retain-alpha-numeric|text-to-screaming-snake-case|dateTime-to-change-of-month|dateTime-to-iso-day-of-year|dateTime-to-length-of-month|file-to-update-datetime-utc|numeric-is-negative-or-zero|numeric-is-positive-or-zero|text-to-collapse-whitespace|text-to-without-whitespaces|dateTime-to-ceiling-minute|dateTime-to-change-of-hour|dateTime-to-change-of-year|dateTime-to-first-in-month|dat